import{_ as d,a0 as l,w as i,s as r,I as s,x as a,a1 as t,A as c,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"10 個讓你進入 Emacs 世界的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"10 個讓你進入 Emacs 世界的技巧 | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10 個讓你進入 Emacs 世界的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10 個讓你進入 Emacs 世界的技巧 | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20200310 Getting started with Emacs","title":"10 個讓你進入 Emacs 世界的技巧","tag":"202011","desc":""},"relativePath":"202011/20200310 Getting started with Emacs.md","filePath":"[post].md"}'),p={name:"202011/20200310 Getting started with Emacs.md"};function n(u,e,E,h,f,b){const o=l("Link");return i(),r("div",null,[e[23]||(e[23]=s("h1",{id:"_10-個讓你進入-emacs-世界的技巧",tabindex:"-1"},[a("10 個讓你進入 Emacs 世界的技巧 "),s("a",{class:"header-anchor",href:"#_10-個讓你進入-emacs-世界的技巧","aria-label":"Permalink to “10 個讓你進入 Emacs 世界的技巧”"},"​")],-1)),e[24]||(e[24]=s("blockquote",null,[s("p",null,"10 個技巧，讓你深入這個有用的開源文本編輯器的世界。")],-1)),e[25]||(e[25]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202011/29/103757lccy9ljxiowooyzy.jpg",alt:""})],-1)),s("p",null,[e[1]||(e[1]=a("很多人都説想學 ",-1)),t(o,{href:"https://opensource.com/downloads/emacs-cheat-sheet"},{default:c(()=>[...e[0]||(e[0]=[a("Emacs",-1)])]),_:1}),e[2]||(e[2]=a("，但很多人在短暫的接觸後就退縮了。這並不是因為 Emacs 不好，也不是 Emacs 複雜。我相信，問題在於人們其實並不想“學習” Emacs，而是他們想習慣 Emacs 的傳統。他們想了解那些神秘的鍵盤快捷鍵和不熟悉的術語。他們想按照他們認為的“使用目的”來使用 Emacs。",-1))]),e[26]||(e[26]=s("p",null,[a("我很同情這一點，因為我對 Emacs 的感覺就是這樣。我以為真正的 Emacs 用户都只會在終端裏面運行，從來不用方向鍵和菜單，更不會用鼠標。這是個阻止自己開始使用 Emacs 的好辦法。有足夠多的獨特的 "),s("code",null,".emacs"),a(" 配置文件證明，如果説 Emacs 用户有一個共同的變化，那就是每個人使用 Emacs 的方式不同。")],-1)),e[27]||(e[27]=s("p",null,"學習 Emacs 很容易。愛上 Emacs 才是最難的。要愛上 Emacs，你必須發現它所擁有的功能，而這些功能是你一直在尋找的，有時你並不知道你已經錯過了它們。這需要經驗。",-1)),e[28]||(e[28]=s("p",null,"獲得這種經驗的唯一方法就是從一開始就積極使用 Emacs。這裏有十個小提示，可以幫助你找出最適合你的方法。",-1)),e[29]||(e[29]=s("h3",{id:"從-gui-開始",tabindex:"-1"},[a("從 GUI 開始 "),s("a",{class:"header-anchor",href:"#從-gui-開始","aria-label":"Permalink to “從 GUI 開始”"},"​")],-1)),s("p",null,[e[5]||(e[5]=a("Emacs（以及它的友好競爭者 ",-1)),t(o,{href:"https://opensource.com/downloads/cheat-sheet-vim"},{default:c(()=>[...e[3]||(e[3]=[a("Vim",-1)])]),_:1}),e[6]||(e[6]=a("）最偉大的事情之一是它可以在終端中運行，這在你 SSH 進入服務器時很有用，但在過去 15 年來製造的計算機上意義不大。Emacs 的 GUI 版本可以在極度",-1)),t(o,{href:"https://opensource.com/article/17/2/pocketchip-or-pi"},{default:c(()=>[...e[4]||(e[4]=[a("低功耗的設備",-1)])]),_:1}),e[7]||(e[7]=a("上運行，它有很多實用的功能，無論是新手還是有經驗的用户都可以使用它。",-1))]),e[30]||(e[30]=m('<p>例如，如果你不知道如何在 Emacs 中只用鍵盤快捷鍵複製一個單詞，編輯菜單的複製、剪切和粘貼選擇提供了最輕鬆的路徑。沒有理由因為選擇了 Emacs 而懲罰自己。使用它的菜單，用鼠標選擇區域，點擊緩衝區內的按鈕，不要讓陌生感阻礙你的工作效率。</p><p><img src="https://opensource.com/sites/default/files/uploads/emacs-slackware.jpg" alt="Emacs slackware" title="Emacs slackware"></p><p>這些功能被內置到 Emacs 中，是因為用户在使用它們。你應該在你需要的時候使用它們，而當你最終在 VT100 終端上通過 SSH 使用 Emacs，沒有 <code>Alt</code> 或方向鍵的時候，你才應該使用這些晦澀的命令。</p><h3 id="習慣術語" tabindex="-1">習慣術語 <a class="header-anchor" href="#習慣術語" aria-label="Permalink to “習慣術語”">​</a></h3><p>Emacs 的 UI 元素有着特殊的術語。個人計算的發展並不是建立在相同的術語上，所以很多術語對現代計算機用户來説比較陌生，還有一些術語雖然相同，但含義不同。下面是一些最常見的術語。</p><ul><li><ruby>框架<rt>Frame</rt></ruby>。在 Emacs 中，“框架”就是現代計算機所説的“窗口”。</li><li><ruby>緩衝區<rt>Buffer</rt></ruby>：“緩衝區”是 Emacs 的一個通信通道。它可以作為 Emacs 進程的命令列，也可以作為 shell，或者只是一個文件的內容。</li><li><ruby>窗口<rt>Window</rt></ruby>：“窗口”是你進入一個緩衝區的視角。</li><li><ruby>迷你緩衝區<rt>Mini-buffer</rt></ruby>。它是主要的命令列，位於 Emacs 窗口的底部。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/emacs-tutorial-map.png" alt="Emacs tutorial map" title="Emacs tutorial map"></p><h3 id="讓-emacs-的修飾鍵變得更有意義" tabindex="-1">讓 Emacs 的修飾鍵變得更有意義 <a class="header-anchor" href="#讓-emacs-的修飾鍵變得更有意義" aria-label="Permalink to “讓 Emacs 的修飾鍵變得更有意義”">​</a></h3><p>在 PC 鍵盤上，<code>Ctrl</code> 鍵被稱為 <code>C</code>，<code>Alt</code> 鍵被稱為 <code>M</code>，這些鍵並不是 <code>C</code> 和 <code>M</code> 鍵，由於它們總是與相應的字母或符號鍵配對，所以在文檔中很容易識別。</p><p>例如，<code>C-x</code> 在現代鍵盤符號中的意思是 <code>Ctrl+X</code>，<code>M-x</code> 是 <code>Alt+X</code>。就像你從任何應用程序中剪切文本時一樣，同時按下這兩個鍵。</p><p>不過，還有另一個層次的鍵盤快捷鍵，與現代電腦上的任何東西都完全不同。有時，鍵盤快捷鍵並不只是一個鍵組合，而是由一系列的按鍵組成。</p><p>例如，<code>C-x C-f</code> 的意思是像往常一樣按 <code>Ctrl+X</code>，然後再按 <code>Ctrl+C</code>。</p><p>有時，一個鍵盤快捷鍵有混合的鍵型。組合鍵 <code>C-x 3</code> 意味着像往常一樣按 <code>Ctrl+X</code>，然後按數字 <code>3</code> 鍵。</p><p>Emacs 之所以能做到這些花哨的強力組合，是因為某些鍵會讓 Emacs 進入一種特殊的命令模式。如果你按 <code>C-X</code>（也就是 <code>Ctrl+X</code>），就是告訴 <code>Emacs</code> 進入空閒狀態，等待第二個鍵或鍵盤快捷鍵。</p><p>Emacs 的文檔，無論是官方的還是非官方的，都有很多鍵盤快捷鍵。在心裏練習把 <code>C</code> 鍵翻譯成 <code>Ctrl</code> 鍵，<code>M</code> 鍵翻譯成 <code>Alt</code> 鍵，那麼這些文檔對你來説都會變得更有意義。</p><h3 id="剪切、複製和粘貼的備用快捷方式" tabindex="-1">剪切、複製和粘貼的備用快捷方式 <a class="header-anchor" href="#剪切、複製和粘貼的備用快捷方式" aria-label="Permalink to “剪切、複製和粘貼的備用快捷方式”">​</a></h3><p>從規範上，複製文本是通過一系列的鍵盤快捷鍵進行的，這些快捷鍵取決於你想要複製或剪切的方式。</p><p>例如，你可以用 <code>M-d</code>（<code>Alt+d</code> 的 Emacs 行話）剪切一整個單詞，或者用<code>C-k</code>（<code>Ctrl+K</code>）剪切一整行，或者用 <code>M-m</code>（<code>Alt+M</code>）剪切一個高亮區域。如果你想的話，你可以習慣這樣，但如果你喜歡 <code>Ctrl+C</code> 和 <code>Ctrl+X</code> 和 <code>Ctrl-V</code>，那麼你可以用這些來代替。</p><p>啓用現代的“剪切-複製-粘貼”需要激活一個名為 CUA（<ruby>通用用户訪問<rt>Common User Access</rt></ruby>）的功能。要激活 CUA，請單擊“選項”菜單並選擇“使用 CUA 鍵”。啓用後，<code>C-c</code> 複製高亮顯示的文本，<code>C-x</code> 剪切高亮顯示的文本，<code>C-v</code> 粘貼文本。這個模式只有在你選擇了文本之後才會實際激活，所以你仍然可以學習 Emacs 通常使用的 <code>C-x</code> 和 <code>C-c</code> 綁定。</p><h3 id="用哪個都好" tabindex="-1">用哪個都好 <a class="header-anchor" href="#用哪個都好" aria-label="Permalink to “用哪個都好”">​</a></h3><p>Emacs 是一個應用程序，它不會意識到你對它的感情或忠誠度。如果你想只用 Emacs 來完成那些“感覺”適合 Emacs 的任務，而用不同的編輯器（比如 Vim）來完成其他任務，你可以這樣做。</p><p>你與一個應用程序的交互會影響你的工作方式，所以如果 Emacs 中所需要的按鍵模式與特定任務不一致，那麼就不要強迫自己使用 Emacs 來完成該任務。Emacs 只是眾多可供你使用的開源工具之一，沒有理由讓自己只限於一種工具。</p><h3 id="探索新函數" tabindex="-1">探索新函數 <a class="header-anchor" href="#探索新函數" aria-label="Permalink to “探索新函數”">​</a></h3><p>Emacs 所做的大部分工作都是一個 elisp 函數，它可以從菜單選擇和鍵盤快捷鍵調用，或者在某些情況下從特定事件中調用。所有的函數都可以從迷你緩衝區（Emacs 框架底部的命令列）執行。理論上，你甚至可以通過鍵入 <code>forward-word</code> 和 <code>backward-word</code> 以及 <code>next-line</code> 和 <code>previous-line</code> 等函數來導航光標。這肯定是無比低效的，但這就是一種直接訪問你運行的代碼的方式。在某種程度上，Emacs 就是自己的 API。</p><p>你可以通過在社區Blog上閲讀有關 Emacs 的資料來了解新函數，或者你可以採取更直接的方法，使用描述函數（<code>describe-function</code>）。要獲得任何函數的幫助，按 <code>M-x</code>（也就是 <code>Alt+X</code>），然後輸入 <code>describe-function</code>，然後按回車鍵。系統會提示你輸入一個函數名稱，然後顯示該函數的描述。</p><p>你可以通過鍵入<code>M-x（</code>Alt+X<code>），然後鍵入 </code>?` 來獲得所有可用函數的列表。</p><p>你也可以在輸入函數時，通過按 <code>M-x</code> 鍵，然後輸入 <code>auto-complete-mode</code>，再按回車鍵，獲得彈出的函數描述。激活該模式後，當你在文檔中鍵入任何 Emacs 函數時，都會向你提供自動補完選項，以及函數的描述。</p><p><img src="https://opensource.com/sites/default/files/uploads/emacs-function.jpg" alt="Emacs function" title="Emacs function"></p><p>當你找到一個有用的函數並使用它時，Emacs 會告訴你它的鍵盤綁定，如果有的話。如果沒有的話，你可以通過打開你的 <code>$HOME/.emacs</code> 配置文件並輸入鍵盤快捷鍵來自己分配一個。語法是 <code> global-set-key</code>，後面是你要使用的鍵盤快捷鍵，然後是你要調用的函數。</p><p>例如，要將 <code>screenwriter-slugline</code> 函數分配一個鍵盤綁定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(global-set-key (kbd “C-c s”) &#39;screenwriter-slugline)</span></span></code></pre></div><p>重新加載配置文件，鍵盤快捷鍵就可以使用了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>M-x load-file ~/.emacs</span></span></code></pre></div><h3 id="緊急按鈕" tabindex="-1">緊急按鈕 <a class="header-anchor" href="#緊急按鈕" aria-label="Permalink to “緊急按鈕”">​</a></h3><p>當你使用 Emacs 並嘗試新的函數時，你一定會開始調用一些你並不想調用的東西。Emacs 中通用的緊急按鈕是 <code>C-g</code>（就是 <code>Ctrl+G</code>）。</p><p>我通過將 G 與 GNU 聯繫起來來記住這一點，我想我是在呼籲 GNU 將我從一個錯誤的決定中拯救出來，但請隨意編造你自己的記憶符號。</p><p>如果你按幾下 <code>C-g</code>，Emacs 的迷你緩衝區就會回到潛伏狀態，彈出窗口被隱藏，你又回到了一個普通的、無聊的文本編輯器的安全狀態。</p><h3 id="忽略鍵盤快捷鍵" tabindex="-1">忽略鍵盤快捷鍵 <a class="header-anchor" href="#忽略鍵盤快捷鍵" aria-label="Permalink to “忽略鍵盤快捷鍵”">​</a></h3><p>潛在的鍵盤快捷鍵太多，在這裏無法一一總結，更不希望你能記住。這是設計好的。Emacs 的目的是為了定製，當人們為 Emacs 編寫插件時，他們可以定義自己的特殊鍵盤快捷鍵。</p><p>我們的想法不是要馬上記住所有的快捷鍵。相反，你的目標是讓你在使用 Emacs 時感到舒適。你在 Emacs 中變得越舒適，你就越會厭倦總是求助於菜單欄，你就會開始記住對你重要的組合鍵。</p><p>根據自己在 Emacs 中通常做的事情，每個人都有自己喜歡的快捷方式。一個整天用 Emacs 寫代碼的人可能知道運行調試器或啓動特定語言模式的所有鍵盤快捷鍵，但對 Org 模式或 Artist 模式一無所知。這很自然，也很好。</p><h3 id="使用-bash-時練習-emacs" tabindex="-1">使用 Bash 時練習 Emacs <a class="header-anchor" href="#使用-bash-時練習-emacs" aria-label="Permalink to “使用 Bash 時練習 Emacs”">​</a></h3><p>瞭解 Emacs 鍵盤快捷鍵的一個好處是，其中許多快捷鍵也適用於 Bash。</p><ul><li><code>C-a</code>：到行首</li><li><code>C-e</code>：到行尾</li><li><code>C-k</code>：剪切整行</li><li><code>M-f</code>：向前一個字</li><li><code>M-b</code>：向後一個字</li><li><code>M-d</code>：剪切一個字</li><li><code>C-y</code>：貼回（粘貼）最近剪切的內容</li><li><code>M-Shift-U</code>：大寫一個詞</li><li><code>C-t</code>：交換兩個字符（例如，<code>sl</code> 變成 <code>ls</code>）</li></ul><p>還有更多的例子，它能讓你與 Bash 終端的交互速度超乎你的想像。</p><h3 id="包" tabindex="-1">包 <a class="header-anchor" href="#包" aria-label="Permalink to “包”">​</a></h3><p>Emacs 有一個內置的包管理器來幫助你發現新的插件。它的包管理器包含了幫助你編輯特定類型文本的模式（例如，如果你經常編輯 JSON 文件，你可以嘗試使用 ejson 模式）、嵌入的應用程序、主題、拼寫檢查選項、linter 等。這就是 Emacs 有可能成為你日常計算的關鍵所在；一旦你找到一個優秀的 Emacs 包，你可能離不開它了。</p><p><img src="https://opensource.com/sites/default/files/uploads/emacs-emoji_0.jpg" alt="Emacs emoji" title="Emacs emoji"></p><p>你可以按 <code>M-x</code>（就是 <code>Alt+X</code>）鍵，然後輸入 <code>package-list-packages</code> 命令，再按回車鍵來瀏覽包。軟件包管理器在每次啓動時都會更新緩存，所以第一次使用時要耐心等待它下載可用軟件包的列表。一旦加載完畢，你可以用鍵盤或鼠標進行導航（記住，Emacs 是一個 GUI 應用程序）。每一個軟件包的名稱都是一個按鈕，所以你可以將光標移到它上面，然後按回車鍵，或者直接用鼠標點擊它。你可以在 Emacs 框架中出現的新窗口中閲讀有關軟件包的信息，然後用安裝按鈕來安裝它。</p><p>有些軟件包需要特殊的配置，有時會在它的描述中列出，但有時需要你訪問軟件包的主頁來閲讀更多的信息。例如，自動完成包 <code>ac-emoji</code> 很容易安裝，但需要你定義一個符號字體。無論哪種方式都可以使用，但你只有在安裝了字體的情況下才能看到相應的表情符號，除非你訪問它的主頁，否則你可能不會知道。</p><h3 id="俄羅斯方塊" tabindex="-1">俄羅斯方塊 <a class="header-anchor" href="#俄羅斯方塊" aria-label="Permalink to “俄羅斯方塊”">​</a></h3><p>Emacs 有遊戲，信不信由你。有數獨、拼圖、掃雷、一個好玩的心理治療師，甚至還有俄羅斯方塊。這些並不是特別有用，但在任何層面上與 Emacs 進行交互都是很好的練習，遊戲是讓你在 Emacs 中花費時間的好方法。</p><p><img src="https://opensource.com/sites/default/files/uploads/emacs-tetris.jpg" alt="Emacs tetris" title="Emacs tetris"></p><p>俄羅斯方塊也是我最初接觸 Emacs 的方式，所以在該遊戲的所有版本中，Emacs 版本才是我真正的最愛。</p><h3 id="使用-emacs" tabindex="-1">使用 Emacs <a class="header-anchor" href="#使用-emacs" aria-label="Permalink to “使用 Emacs”">​</a></h3><p>GNU Emacs 之所以受歡迎，是因為它的靈活性和高度可擴展性。人們習慣了 Emacs 的鍵盤快捷鍵，以至於他們習慣性地嘗試在其他所有的應用程序中使用這些快捷鍵，他們將應用程序構建到 Emacs 中，所以他們永遠不需要離開。如果你想讓 Emacs 在你的計算生活中扮演重要角色，最終的關鍵是擁抱未知，開始使用 Emacs。磕磕絆絆地，直到你發現如何讓它為你工作，然後安下心來，享受 40 年的舒適生活。</p><hr>',57)),s("p",null,[e[9]||(e[9]=a("via: ",-1)),t(o,{href:"https://opensource.com/article/20/3/getting-started-emacs"},{default:c(()=>[...e[8]||(e[8]=[a("https://opensource.com/article/20/3/getting-started-emacs",-1)])]),_:1})]),s("p",null,[e[14]||(e[14]=a("作者：",-1)),t(o,{href:"https://opensource.com/users/seth"},{default:c(()=>[...e[10]||(e[10]=[a("Seth Kenlon",-1)])]),_:1}),e[15]||(e[15]=a(" 選題：",-1)),t(o,{href:"https://github.com/lujun9972"},{default:c(()=>[...e[11]||(e[11]=[a("lujun9972",-1)])]),_:1}),e[16]||(e[16]=a(" 譯者：",-1)),t(o,{href:"https://github.com/wxy"},{default:c(()=>[...e[12]||(e[12]=[a("wxy",-1)])]),_:1}),e[17]||(e[17]=a(" 校對：",-1)),t(o,{href:"https://github.com/wxy"},{default:c(()=>[...e[13]||(e[13]=[a("wxy",-1)])]),_:1})]),s("p",null,[e[20]||(e[20]=a("本文由 ",-1)),t(o,{href:"https://github.com/LCTT/TranslateProject"},{default:c(()=>[...e[18]||(e[18]=[a("LCTT",-1)])]),_:1}),e[21]||(e[21]=a(" 原創編譯，",-1)),t(o,{href:"https://linux.cn/"},{default:c(()=>[...e[19]||(e[19]=[a("Linux中國",-1)])]),_:1}),e[22]||(e[22]=a(" 榮譽推出",-1))])])}const x=d(p,[["render",n]]);export{k as __pageData,x as default};
